import assert from "node:assert/strict";
import {describe, it} from "node:test";
import {buildCardBlock, buildCardsInsertion, wrapNextCloze} from "../src/card-format";
import {prepareClozePreview} from "../src/cloze-preview";
import {MANAGED_TAG} from "../src/constants";
import {prepareFieldsForAnki} from "../src/field-encoding";
import {parseCardsDocument} from "../src/parser";
import {deckNameForPath, extractPathFromTags, makePathTag, makeUuidTag, sanitizeUserTag} from "../src/tags";

describe("parseCardsDocument", () => {
	it("parses cloze and basic cards and writes uuid/path", () => {
		const source = `---
tags:
  - math
  - python/tools
---
# Note
inline #review

# Cards
## 拉格朗日中值定理
在闭区间上{{c1::连续}}。
tag: theorem
---
Front
## 简答题
请简述 \`list\` 和 \`tuple\` 的区别。
Back
\`list\` 可变，\`tuple\` 不可变。
tags: python basic
---
`;

		const parsed = parseCardsDocument(source, "folder/page.md", {
			ensureIdentities: true,
			rootDeckName: "Obsidian",
		});

		assert.equal(parsed.cards.length, 2);
		assert.equal(parsed.changed, true);
		assert.match(parsed.updatedSource, /uuid: [0-9a-f-]{36}/);
		assert.match(parsed.updatedSource, /path: folder\/page\.md/);

		const cloze = parsed.cards[0];
		assert.ok(cloze);
		assert.equal(cloze.modelName, "Cloze-Modern");
		assert.deepEqual(cloze.fields, {Text: "## 拉格朗日中值定理\n在闭区间上{{c1::连续}}。", Extra: ""});
		assert.equal(cloze.deckName, "Obsidian::folder::page.md");
		assert.ok(cloze.ankiTags.includes(MANAGED_TAG));
		assert.ok(cloze.ankiTags.includes(makeUuidTag(cloze.uuid)));
		assert.ok(cloze.ankiTags.includes(makePathTag("folder/page.md")));
		assert.ok(cloze.ankiTags.includes("math"));
		assert.ok(cloze.ankiTags.includes("python::tools"));
		assert.ok(cloze.ankiTags.includes("review"));
		assert.ok(cloze.ankiTags.includes("theorem"));

		const basic = parsed.cards[1];
		assert.ok(basic);
		assert.equal(basic.modelName, "Basic-Modern");
		assert.deepEqual(basic.fields, {
			Front: "## 简答题\n请简述 `list` 和 `tuple` 的区别。",
			Back: "`list` 可变，`tuple` 不可变。",
		});
		assert.ok(basic.ankiTags.includes("basic"));
	});

	it("honors explicit type aliases and preserves existing identity", () => {
		const source = `# Cards
type: basic-reversed
Front
A
Back
B
uuid: 11111111-1111-4111-8111-111111111111
path: old/path.md
---
`;

		const parsed = parseCardsDocument(source, "new/path.md", {
			ensureIdentities: true,
			rootDeckName: "Deck",
		});

		assert.equal(parsed.cards.length, 1);
		assert.equal(parsed.cards[0]?.uuid, "11111111-1111-4111-8111-111111111111");
		assert.equal(parsed.cards[0]?.modelName, "Basic-Modern-Reversed");
		assert.match(parsed.updatedSource, /path: new\/path\.md/);
		assert.doesNotMatch(parsed.updatedSource, /old\/path\.md/);
	});

	it("treats blank identity lines as missing identity", () => {
		const source = `# Cards
## Blank identity
{{c1::generated}}
uuid:
path:
---
`;

		const parsed = parseCardsDocument(source, "moved/page.md", {
			ensureIdentities: true,
			rootDeckName: "Obsidian",
		});

		assert.equal(parsed.cards.length, 1);
		assert.match(parsed.cards[0]?.uuid ?? "", /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
		assert.match(parsed.updatedSource, /uuid: [0-9a-f-]{36}/);
		assert.match(parsed.updatedSource, /path: moved\/page\.md/);
		assert.doesNotMatch(parsed.updatedSource, /uuid:\s*\npath:/);
	});

	it("encodes path tags reversibly", () => {
		const tag = makePathTag("目录/页面 name.md");
		assert.equal(extractPathFromTags([tag]), "目录/页面 name.md");
	});
});

describe("tag and deck helpers", () => {
	it("sanitizes Anki tags and mirrors paths into deck names", () => {
		assert.equal(sanitizeUserTag("#python/tools"), "python::tools");
		assert.equal(sanitizeUserTag(" spaced tag "), "spaced_tag");
		assert.equal(deckNameForPath("Obsidian", "a/b.md"), "Obsidian::a::b.md");
	});
});

describe("Anki field encoding", () => {
	it("encodes braces inside cloze answers without changing source fields", () => {
		const fields = {
			Text: "$$ {{c1::\\frac{\\text{A}}{\\text{B}}}} $$",
			Extra: "$$ \\frac{a}{b} $$",
		};

		assert.deepEqual(prepareFieldsForAnki(fields), {
			Text: "$$ {{c1::\\frac&#123;\\text&#123;A&#125;&#125;&#123;\\text&#123;B&#125;&#125;}} $$",
			Extra: "$$ \\frac{a}{b} $$",
		});
	});

	it("escapes HTML while keeping cloze delimiters readable to Anki", () => {
		assert.deepEqual(prepareFieldsForAnki({
			Text: "{{c1::<tag> {x} & y}}",
			Extra: "<extra>",
		}), {
			Text: "{{c1::&lt;tag&gt; &#123;x&#125; &amp; y}}",
			Extra: "&lt;extra&gt;",
		});
	});
});

describe("quick card builder", () => {
	it("creates human-editable blocks with blank identity placeholders", () => {
		const block = buildCardBlock({
			kind: "basic-reversed",
			front: "What is P/E?",
			back: "Price divided by earnings.",
			tags: "finance valuation",
			syncAfterInsert: false,
		});

		assert.equal(block, [
			"type: Basic-Modern-Reversed",
			"Front",
			"What is P/E?",
			"Back",
			"Price divided by earnings.",
			"tags: finance valuation",
			"uuid:",
			"path:",
			"",
		].join("\n"));
	});

	it("wraps selected text as the next cloze deletion", () => {
		assert.deepEqual(wrapNextCloze("A {{c1::B}} C D", 14, 15), {
			value: "A {{c1::B}} C {{c2::D}}",
			selectionStart: 20,
			selectionEnd: 21,
		});
	});

	it("inserts an editable cloze placeholder when nothing is selected", () => {
		assert.deepEqual(wrapNextCloze("A B", 1, 1), {
			value: "A{{c1::answer}} B",
			selectionStart: 7,
			selectionEnd: 13,
		});
	});
});

describe("quick card insertion", () => {
	const clozeBlock = buildCardBlock({
		kind: "cloze",
		front: "A {{c1::B}}",
		back: "",
		tags: "",
		syncAfterInsert: false,
	});

	it("appends a new cards section at the end of a note without one", () => {
		const source = "# Note\n\nBody text.\n";
		assert.deepEqual(buildCardsInsertion(source, clozeBlock), {
			offset: source.length,
			text: `\n# Cards\n${clozeBlock}---\n`,
		});
	});

	it("adds a separator before appending to an existing cards section", () => {
		const source = "# Note\n\n# Cards\nold card\n";
		assert.deepEqual(buildCardsInsertion(source, clozeBlock), {
			offset: source.length,
			text: `---\n${clozeBlock}---\n`,
		});
	});

	it("does not add a separator when the section already ends with one", () => {
		const source = "# Cards\nold card\n---\n";
		assert.deepEqual(buildCardsInsertion(source, clozeBlock), {
			offset: source.length,
			text: `${clozeBlock}---\n`,
		});
	});

	it("skips the separator for an empty cards section", () => {
		const source = "# Cards\n";
		assert.deepEqual(buildCardsInsertion(source, clozeBlock), {
			offset: source.length,
			text: `${clozeBlock}---\n`,
		});
	});
});

describe("cloze preview rendering", () => {
	it("masks clozes outside math with a placeholder span", () => {
		assert.equal(
			prepareClozePreview("答案是 {{c1::42}}。"),
			'答案是 <span class="oas-cloze" title="42">[...]</span>。',
		);
	});

	it("strips cloze hints from the placeholder title", () => {
		assert.equal(
			prepareClozePreview("{{c1::answer::hint}}"),
			'<span class="oas-cloze" title="answer">[...]</span>',
		);
	});

	it("masks clozes inside dollar math without leaking HTML", () => {
		assert.equal(
			prepareClozePreview("$${{c1::\\frac{1}{2}}}$$ 和 $x_{{c2::n}}$"),
			"$$\\text{[...]}$$ 和 $x_\\text{[...]}$",
		);
	});

	it("renders bracket math delimiters as display math", () => {
		assert.equal(
			prepareClozePreview("\\[\n{{c1::E[X]}} = \\sum_x x\n\\]"),
			"$$\n\\text{[...]} = \\sum_x x\n$$",
		);
	});

	it("renders parenthesis math delimiters as inline math", () => {
		assert.equal(
			prepareClozePreview("重复交易 \\(N\\) 次"),
			"重复交易 $N$ 次",
		);
	});

	it("masks clozes inside parenthesis math", () => {
		assert.equal(
			prepareClozePreview("即 \\({{c2::p_1x_1+\\cdots+p_kx_k}}\\)，即期望"),
			"即 $\\text{[...]}$，即期望",
		);
	});

	it("escapes HTML special characters in placeholder titles", () => {
		assert.equal(
			prepareClozePreview('{{c1::a <b> & "c"}}'),
			'<span class="oas-cloze" title="a &lt;b&gt; &amp; &quot;c&quot;">[...]</span>',
		);
	});
});

describe("cards section boundaries", () => {
	it("ends the cards section at the next heading of the same level", () => {
		const source = `# Cards
## 真正的卡片
答案是 {{c1::42}}。
---
# References
这段文字不是卡片，也不应被改写。
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: true, rootDeckName: "Obsidian"});

		assert.equal(parsed.cards.length, 1);
		assert.equal(parsed.cards[0]?.modelName, "Cloze-Modern");
		assert.match(parsed.updatedSource, /# References\n这段文字不是卡片，也不应被改写。\n?$/);
		assert.ok(!parsed.updatedSource.includes("这段文字不是卡片，也不应被改写。\nuuid:"));
	});

	it("keeps subheadings inside cards when the cards heading is a level up", () => {
		const source = `# Cards
## 卡片内的小标题
{{c1::内容}}
---
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: false, rootDeckName: "Obsidian"});
		assert.equal(parsed.cards.length, 1);
		const fields = parsed.cards[0]?.fields;
		assert.ok(fields && "Text" in fields);
		assert.match(fields.Text, /## 卡片内的小标题/);
	});

	it("ignores a cards heading inside a code fence", () => {
		const source = `# 说明文档

\`\`\`markdown
# Cards
示例内容
\`\`\`
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: false, rootDeckName: "Obsidian"});
		assert.equal(parsed.cards.length, 0);
		assert.equal(parsed.cardsSection, null);
	});

	it("does not split a card on a separator inside a code fence", () => {
		const source = `# Cards
Front
## 代码示例
\`\`\`yaml
---
key: value
\`\`\`
Back
答案
---
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: false, rootDeckName: "Obsidian"});
		assert.equal(parsed.cards.length, 1);
		const fields = parsed.cards[0]?.fields;
		assert.ok(fields && "Front" in fields && fields.Front.includes("---"));
	});

	it("keeps metadata-looking lines that appear inside code fences", () => {
		const source = `# Cards
Front
## 配置示例
\`\`\`yaml
tags: demo
\`\`\`
Back
答案
---
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: false, rootDeckName: "Obsidian"});
		assert.equal(parsed.cards.length, 1);
		const card = parsed.cards[0];
		assert.ok(card && "Front" in card.fields && card.fields.Front.includes("tags: demo"));
		assert.ok(!card.userTags.includes("demo"));
	});
});

describe("duplicate card identities", () => {
	it("assigns a fresh uuid to a duplicated block and keeps the first one", () => {
		const uuid = "11111111-1111-4111-8111-111111111111";
		const source = `# Cards
## 卡片甲
{{c1::A}}
uuid: ${uuid}
path: p.md
---
## 卡片乙（复制自甲）
{{c1::B}}
uuid: ${uuid}
path: p.md
---
`;
		const parsed = parseCardsDocument(source, "p.md", {ensureIdentities: true, rootDeckName: "Obsidian"});

		assert.equal(parsed.cards.length, 2);
		assert.equal(parsed.cards[0]?.uuid, uuid);
		assert.notEqual(parsed.cards[1]?.uuid, uuid);
		assert.match(parsed.cards[1]?.uuid ?? "", /^[0-9a-f-]{36}$/);
		assert.match(parsed.updatedSource, new RegExp(`## 卡片乙（复制自甲）\\n\\{\\{c1::B\\}\\}\\nuuid: ${parsed.cards[1]?.uuid}`));
	});
});

describe("quick card insertion edge cases", () => {
	it("adds a separator when the section ends with text that merely ends in dashes", () => {
		const block = buildCardBlock({kind: "cloze", front: "A {{c1::B}}", back: "", tags: "", syncAfterInsert: false});
		const source = "# Cards\nfinal score 9---\n";
		const insertion = buildCardsInsertion(source, block);
		assert.equal(insertion.text, `---\n${block}---\n`);
	});
});

import {App, MarkdownPostProcessorContext, MarkdownRenderer, MarkdownRenderChild, Plugin} from "obsidian";
import {prepareClozePreview} from "./cloze-preview";
import {ParsedCard, parseCardsDocument} from "./parser";

export function registerCardPreview(plugin: Plugin, app: App, getRootDeckName: () => string): void {
	plugin.registerMarkdownPostProcessor(async (element, context) => {
		const heading = findCardsHeading(element);
		if (!heading || heading.dataset.oasPreviewProcessed === "true") return;
		heading.dataset.oasPreviewProcessed = "true";

		const file = app.vault.getFileByPath(context.sourcePath);
		if (!file) {
			delete heading.dataset.oasPreviewProcessed;
			return;
		}

		const source = await app.vault.cachedRead(file);
		const parsed = parseCardsDocument(source, file.path, {
			ensureIdentities: false,
			rootDeckName: getRootDeckName(),
		});

		if (parsed.cards.length === 0) {
			delete heading.dataset.oasPreviewProcessed;
			return;
		}

		const container = document.createElement("div");
		container.addClass("oas-card-preview-list");

		for (const card of parsed.cards) {
			container.appendChild(await renderCardPreview(app, card, context));
		}

		heading.insertAdjacentElement("afterend", container);
		hideOriginalCardSource(heading, container);
	});
}

async function renderCardPreview(app: App, card: ParsedCard, context: MarkdownPostProcessorContext): Promise<HTMLElement> {
	const preview = document.createElement("article");
	preview.addClass("oas-card-preview");
	preview.dataset.modelName = card.modelName;
	const renderChild = new MarkdownRenderChild(preview);
	context.addChild(renderChild);

	const header = document.createElement("div");
	header.addClass("oas-card-preview-header");
	header.createEl("span", {text: card.modelName});
	header.createEl("span", {text: card.uuid});
	preview.appendChild(header);

	if ("Text" in card.fields) {
		const content = preview.createDiv({cls: "oas-rendered-content"});
		await renderObsidianMarkdown(renderChild, app, content, prepareClozePreview(card.fields.Text), context.sourcePath);
	} else {
		preview.appendChild(await renderBasicSection(renderChild, app, context, "Front", card.fields.Front));
		preview.appendChild(await renderBasicSection(renderChild, app, context, "Back", card.fields.Back));
	}

	const footer = document.createElement("div");
	footer.addClass("oas-card-preview-tags");
	for (const tag of card.userTags) {
		footer.createEl("span", {text: tag});
	}
	if (footer.children.length > 0) preview.appendChild(footer);

	return preview;
}

async function renderBasicSection(renderChild: MarkdownRenderChild, app: App, context: MarkdownPostProcessorContext, label: string, markdown: string): Promise<HTMLElement> {
	const section = document.createElement("section");
	section.addClass("oas-basic-section");
	section.createEl("div", {cls: "oas-basic-section-label", text: label});
	const content = section.createDiv({cls: "oas-rendered-content"});
	await renderObsidianMarkdown(renderChild, app, content, prepareClozePreview(markdown), context.sourcePath);
	return section;
}

async function renderObsidianMarkdown(renderChild: MarkdownRenderChild, app: App, container: HTMLElement, markdown: string, sourcePath: string): Promise<void> {
	await MarkdownRenderer.render(app, markdown, container, sourcePath, renderChild);
}

function findCardsHeading(element: HTMLElement): HTMLElement | null {
	const headings = Array.from(element.querySelectorAll<HTMLElement>("h1,h2,h3,h4,h5,h6"));
	return headings.find((heading) => heading.textContent?.trim().toLowerCase() === "cards") ?? null;
}

function hideOriginalCardSource(heading: HTMLElement, previewContainer: HTMLElement): void {
	const headingLevel = Number(heading.tagName.slice(1));
	let sibling = previewContainer.nextElementSibling as HTMLElement | null;

	while (sibling) {
		const next = sibling.nextElementSibling as HTMLElement | null;
		if (isHeadingAtOrAbove(sibling, headingLevel)) break;
		sibling.addClass("oas-hidden-card-source");
		sibling = next;
	}
}

function isHeadingAtOrAbove(element: HTMLElement, headingLevel: number): boolean {
	if (!/^H[1-6]$/.test(element.tagName)) return false;
	return Number(element.tagName.slice(1)) <= headingLevel;
}

export function trimOuterBlankLines(value: string): string {
	return value.replace(/^\s*\n/g, "").replace(/\n\s*$/g, "").trim();
}

export function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

import {scanClozes} from "./cloze-scan";
import {AnkiFields} from "./parser";

export function prepareFieldsForAnki(fields: AnkiFields): AnkiFields {
	if ("Text" in fields) {
		return {
			Text: encodeClozeInnerBraces(escapeHtml(fields.Text)),
			Extra: escapeHtml(fields.Extra),
		};
	}

	return {
		Front: escapeHtml(fields.Front),
		Back: escapeHtml(fields.Back),
	};
}

function escapeHtml(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");
}

function encodeClozeInnerBraces(value: string): string {
	let result = "";
	let cursor = 0;

	scanClozes(value, ({answerStart, end}) => {
		result += value.slice(cursor, answerStart);
		result += value.slice(answerStart, end).replace(/[{}]/g, (brace) => brace === "{" ? "&#123;" : "&#125;");
		result += "}}";
		cursor = end + 2;
	});

	return result + value.slice(cursor);
}

import {scanClozes} from "./cloze-scan";

export function prepareClozePreview(source: string): string {
	const mathTokens: string[] = [];
	let tokenized = normalizeMathDelimiters(source);

	tokenized = tokenized.replace(/\$\$([\s\S]*?)\$\$/g, (_match, formula: string) => {
		return pushMathToken(mathTokens, `$$${replaceLatexClozes(formula)}$$`);
	});

	tokenized = tokenized.replace(/\$(?!\s)([^$\n]*?\S)\$(?!\d)/g, (_match, formula: string) => {
		return pushMathToken(mathTokens, `$${replaceLatexClozes(formula)}$`);
	});

	tokenized = replaceAnkiClozes(tokenized, (answer) => {
		return `<span class="oas-cloze" title="${escapeAttribute(answer)}">[...]</span>`;
	});

	return tokenized.replace(/%%OAS_MATH_(\d+)%%/g, (_match, index: string) => {
		return mathTokens[Number(index)] ?? "";
	});
}

function pushMathToken(tokens: string[], renderedMath: string): string {
	tokens.push(renderedMath);
	return `%%OAS_MATH_${tokens.length - 1}%%`;
}

function normalizeMathDelimiters(source: string): string {
	return source
		.replace(/\\\[([\s\S]*?)\\\]/g, (_match, formula: string) => `$$${formula}$$`)
		.replace(/\\\(([\s\S]*?)\\\)/g, (_match, formula: string) => `$${formula}$`);
}

function replaceLatexClozes(formula: string): string {
	return replaceAnkiClozes(formula, () => "\\text{[...]}");
}

function replaceAnkiClozes(source: string, replacer: (answer: string) => string): string {
	let result = "";
	let readFrom = 0;

	scanClozes(source, ({start, answerStart, end}) => {
		const answer = stripClozeHint(source.slice(answerStart, end));
		result += source.slice(readFrom, start) + replacer(answer);
		readFrom = end + 2;
	});

	return result + source.slice(readFrom);
}

function stripClozeHint(answer: string): string {
	const hintIndex = answer.indexOf("::");
	return hintIndex >= 0 ? answer.slice(0, hintIndex) : answer;
}

function escapeAttribute(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/"/g, "&quot;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");
}

import {DEFAULT_ROOT_DECK, PATH_TAG_PREFIX, UUID_TAG_PREFIX} from "./constants";

export function encodeBase64Url(value: string): string {
	const bytes = new TextEncoder().encode(value);
	let binary = "";
	for (const byte of bytes) {
		binary += String.fromCharCode(byte);
	}

	return btoa(binary)
		.replace(/\+/g, "-")
		.replace(/\//g, "_")
		.replace(/=+$/g, "");
}

export function decodeBase64Url(value: string): string | null {
	try {
		const padded = value.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(value.length / 4) * 4, "=");
		const binary = atob(padded);
		const bytes = new Uint8Array(binary.length);
		for (let index = 0; index < binary.length; index += 1) {
			bytes[index] = binary.charCodeAt(index);
		}
		return new TextDecoder().decode(bytes);
	} catch {
		return null;
	}
}

export function makeUuidTag(uuid: string): string {
	return `${UUID_TAG_PREFIX}${uuid.toLowerCase()}`;
}

export function extractUuidFromTags(tags: string[]): string | null {
	const uuidTag = tags.find((tag) => tag.startsWith(UUID_TAG_PREFIX));
	return uuidTag ? uuidTag.slice(UUID_TAG_PREFIX.length) : null;
}

export function makePathTag(path: string): string {
	return `${PATH_TAG_PREFIX}${encodeBase64Url(path)}`;
}

export function extractPathFromTags(tags: string[]): string | null {
	const pathTag = tags.find((tag) => tag.startsWith(PATH_TAG_PREFIX));
	return pathTag ? decodeBase64Url(pathTag.slice(PATH_TAG_PREFIX.length)) : null;
}

export function sanitizeUserTag(tag: string): string | null {
	const cleaned = tag
		.trim()
		.replace(/^#+/, "")
		.replace(/\//g, "::")
		.replace(/[\s,]+/g, "_")
		.replace(/[^\p{L}\p{N}_:\-.]+/gu, "_")
		.replace(/^_+|_+$/g, "");

	return cleaned.length > 0 ? cleaned : null;
}

export function uniqueTags(tags: string[]): string[] {
	return Array.from(new Set(tags.filter((tag) => tag.length > 0))).sort((left, right) => left.localeCompare(right));
}

export function deckNameForPath(rootDeckName: string, path: string): string {
	const root = sanitizeDeckSegment(rootDeckName) || DEFAULT_ROOT_DECK;
	const segments = path.split("/").map(sanitizeDeckSegment).filter((segment) => segment.length > 0);
	return [root, ...segments].join("::");
}

function sanitizeDeckSegment(segment: string): string {
	return segment.trim().replace(/::/g, " - ").replace(/[\r\n\t]+/g, " ").replace(/\s+/g, " ");
}

import {
	App,
	ButtonComponent,
	Editor,
	Modal,
	Notice,
	Setting,
	TFile,
} from "obsidian";
import {buildCardBlock, buildCardsInsertion, QuickCardDraft, QuickCardKind, wrapNextCloze} from "./card-format";
import {errorMessage} from "./utils";

export interface QuickCardInsertResult {
	file: TFile;
	shouldSync: boolean;
}

export interface QuickCardModalOptions {
	allowSync: boolean;
	file: TFile | null;
	editor?: Editor;
	initialText?: string;
}

export class QuickCardModal extends Modal {
	private draft: QuickCardDraft = {
		kind: "cloze",
		front: "",
		back: "",
		tags: "",
		syncAfterInsert: false,
	};

	private formContainer: HTMLElement | null = null;
	private createButton: ButtonComponent | null = null;
	private primaryInput: HTMLTextAreaElement | null = null;

	constructor(
		app: App,
		private readonly onInsert: (result: QuickCardInsertResult) => void,
		private readonly onBeforeInsert?: (file: TFile) => void,
		private readonly options: QuickCardModalOptions = {allowSync: true, file: null},
	) {
		super(app);
		if (options.initialText?.trim()) {
			this.draft.front = options.initialText;
		}
	}

	onOpen(): void {
		const {contentEl} = this;
		contentEl.empty();
		this.modalEl.addClass("oas-card-modal");
		this.setTitle("Create Anki card");

		if (!this.options.file) {
			new Setting(contentEl)
				.setName("No target note")
				.setDesc("Open a Markdown note, then create the card from its tab or with this note active.");
		}

		new Setting(contentEl)
			.setName("Type")
			.setDesc("Use cloze for deletion cards, or basic for front/back cards.")
			.addDropdown((dropdown) => {
				dropdown
					.addOption("cloze", "Cloze")
					.addOption("cloze-typing", "Cloze typing")
					.addOption("basic", "Basic")
					.addOption("basic-reversed", "Basic reversed")
					.addOption("basic-typing", "Basic typing")
					.setValue(this.draft.kind)
					.onChange((value) => {
						this.draft.kind = value as QuickCardKind;
						this.renderFields();
						this.updateCreateButton();
					});
			});

		this.formContainer = contentEl.createDiv({cls: "oas-card-modal-fields"});
		this.renderFields();

		new Setting(contentEl)
			.setName("Tags")
			.setDesc("Optional card-local tags, separated by spaces or commas.")
			.addText((text) => {
				text
					.setPlaceholder("Math theorem")
					.setValue(this.draft.tags)
					.onChange((value) => {
						this.draft.tags = value;
					});
			});

		if (this.options.allowSync) {
			new Setting(contentEl)
				.setName("Sync after insert")
				.setDesc("Immediately sync the current page after creating the card.")
				.addToggle((toggle) => {
					toggle
						.setValue(this.draft.syncAfterInsert)
						.onChange((value) => {
							this.draft.syncAfterInsert = value;
						});
				});
		}

		new Setting(contentEl)
			.addButton((button) => button
				.setButtonText("Cancel")
				.onClick(() => this.close()))
			.addButton((button) => {
				this.createButton = button;
				button
					.setButtonText("Insert card")
					.setCta()
					.onClick(() => {
						void this.insertCard();
					});
			});
		this.updateCreateButton();

		this.scope.register(["Mod"], "Enter", () => {
			if (this.canInsert()) {
				void this.insertCard();
			}
			return false;
		});
	}

	onClose(): void {
		this.contentEl.empty();
	}

	private renderFields(): void {
		if (!this.formContainer) return;
		this.formContainer.empty();

		const isBasic = this.draft.kind.startsWith("basic");
		this.primaryInput = null;

		new Setting(this.formContainer)
			.setName(isBasic ? "Front" : "Text")
			.setDesc(isBasic ? "Question side. Markdown and LaTeX are supported." : "Write text normally, then select text and wrap it as cloze.")
			.addTextArea((text) => {
				this.primaryInput = text.inputEl;
				text
					.setPlaceholder(isBasic ? "What is ..." : "The derivative of {{c1::x^2}} is {{c2::2x}}.")
					.setValue(this.draft.front)
					.onChange((value) => {
						this.draft.front = value;
						this.updateCreateButton();
					});
				text.inputEl.rows = 7;
			});

		if (!isBasic) {
			new Setting(this.formContainer)
				.setName("Cloze helper")
				.setDesc("Select text above, then wrap it as the next cloze deletion.")
				.addButton((button) => {
					button
						.setButtonText("Wrap selection")
						.onClick(() => this.wrapPrimarySelectionAsCloze());
				});
		}

		new Setting(this.formContainer)
			.setName(isBasic ? "Back" : "Extra")
			.setDesc(isBasic ? "Answer side." : "Optional back-side notes.")
			.addTextArea((text) => {
				text
					.setPlaceholder(isBasic ? "Answer..." : "Optional explanation...")
					.setValue(this.draft.back)
					.onChange((value) => {
						this.draft.back = value;
					});
				text.inputEl.rows = 5;
			});
	}

	private canInsert(): boolean {
		return this.options.file !== null && this.draft.front.trim().length > 0;
	}

	private updateCreateButton(): void {
		this.createButton?.setDisabled(!this.canInsert());
	}

	private wrapPrimarySelectionAsCloze(): void {
		if (!this.primaryInput) return;

		const result = wrapNextCloze(
			this.primaryInput.value,
			this.primaryInput.selectionStart,
			this.primaryInput.selectionEnd,
		);

		this.draft.front = result.value;
		this.primaryInput.value = result.value;
		this.primaryInput.focus();
		this.primaryInput.setSelectionRange(result.selectionStart, result.selectionEnd);
		this.updateCreateButton();
	}

	private async insertCard(): Promise<void> {
		const file = this.options.file;
		if (!file) {
			new Notice("Open a Markdown note before creating an Anki card.");
			return;
		}

		try {
			const block = buildCardBlock(this.draft);
			this.onBeforeInsert?.(file);
			await insertCardBlock(this.app, file, this.options.editor ?? null, block);
		} catch (error) {
			new Notice(`Could not insert the Anki card: ${errorMessage(error)}`);
			return;
		}

		this.onInsert({file, shouldSync: this.options.allowSync && this.draft.syncAfterInsert});
		this.close();
	}
}

async function insertCardBlock(app: App, file: TFile, editor: Editor | null, block: string): Promise<void> {
	const source = await app.vault.read(file);
	const insertion = buildCardsInsertion(source, block);
	const updated = source.slice(0, insertion.offset) + insertion.text + source.slice(insertion.offset);
	await app.vault.modify(file, updated);

	if (editor) {
		const cursorOffset = insertion.offset + insertion.text.length;
		editor.setCursor(editor.offsetToPos(cursorOffset));
	}
}

export const MANAGED_TAG = "obsidian_anki_sync";
export const UUID_TAG_PREFIX = "obsidian_uuid_";
export const PATH_TAG_PREFIX = "obsidian_path_";

export const DEFAULT_ANKI_CONNECT_URL = "http://127.0.0.1:8765";
export const DEFAULT_ROOT_DECK = "Obsidian";

export const TEMPLATE_SETUP_HINT =
	"Missing Modern Anki note types. Create them with the my_anki_template setup script (anki_connect.py).";

export const SUPPORTED_MODELS = [
	"Cloze-Modern",
	"Cloze-Modern-Typing",
	"Basic-Modern",
	"Basic-Modern-Reversed",
	"Basic-Modern-Typing",
] as const;

export type SupportedModelName = (typeof SUPPORTED_MODELS)[number];

export const MODEL_ALIASES: Record<string, SupportedModelName> = {
	cloze: "Cloze-Modern",
	"cloze-modern": "Cloze-Modern",
	"cloze-type": "Cloze-Modern-Typing",
	"cloze-typing": "Cloze-Modern-Typing",
	"cloze-modern-typing": "Cloze-Modern-Typing",
	basic: "Basic-Modern",
	"basic-modern": "Basic-Modern",
	"basic-reversed": "Basic-Modern-Reversed",
	reversed: "Basic-Modern-Reversed",
	"basic-modern-reversed": "Basic-Modern-Reversed",
	"basic-type": "Basic-Modern-Typing",
	"basic-typing": "Basic-Modern-Typing",
	"basic-modern-typing": "Basic-Modern-Typing",
};

export interface ClozeRange {
	start: number;
	answerStart: number;
	end: number;
}

export function scanClozes(source: string, visit: (range: ClozeRange) => void): void {
	const opener = /\{\{c\d+::/g;
	let match: RegExpExecArray | null;

	while ((match = opener.exec(source)) !== null) {
		const answerStart = opener.lastIndex;
		const end = findClozeEnd(source, answerStart);
		if (end === -1) continue;

		visit({start: match.index, answerStart, end});
		opener.lastIndex = end + 2;
	}
}

export function findClozeEnd(source: string, answerStart: number): number {
	let braceDepth = 0;

	for (let index = answerStart; index < source.length - 1; index += 1) {
		const char = source[index];
		if (char === "{") {
			braceDepth += 1;
			continue;
		}

		if (char !== "}") continue;

		if (braceDepth > 0) {
			braceDepth -= 1;
			continue;
		}

		if (source[index + 1] === "}") {
			return index;
		}
	}

	return -1;
}

import {App, Modal, Notice, Setting, TFile} from "obsidian";
import {AnkiConnectClient, AnkiNoteInfo, getManagedUuid} from "./anki";
import {extractPathFromTags, makePathTag} from "./tags";
import {parseCardsDocument, ParsedCard} from "./parser";
import {AnkiSyncSettings} from "./settings";

export interface SyncSummary {
	scannedFiles: number;
	cards: number;
	created: number;
	updated: number;
	modelChanged: number;
	deleted: number;
	pendingDelete: number;
	filesChanged: number;
}

export interface SyncRuntimeOptions {
	silent?: boolean;
	onBeforeWrite?: (file: TFile) => void;
}

export class AnkiSyncService {
	constructor(
		private readonly app: App,
		private readonly settings: AnkiSyncSettings,
	) {}

	async syncCurrentFile(file: TFile, options?: SyncRuntimeOptions): Promise<SyncSummary> {
		const summary = emptySummary();
		summary.scannedFiles = 1;

		const parsed = await this.parseFile(file, true, options);
		if (!parsed) return summary;

		summary.filesChanged += parsed.changed ? 1 : 0;
		summary.cards = parsed.cards.length;

		const client = await this.readyClient();
		if (parsed.cards.length > 0) {
			await client.validateCardsCanBeAdded(parsed.cards);
			await this.upsertCards(client, parsed.cards, summary);
		}

		const deleteCandidates = await this.currentPathDeleteCandidates(client, file.path, new Set(parsed.cards.map((card) => card.uuid)));
		summary.pendingDelete = deleteCandidates.length;
		await this.deleteCandidates(client, deleteCandidates, summary, options);

		return summary;
	}

	async syncAllFiles(options?: SyncRuntimeOptions): Promise<SyncSummary> {
		const summary = emptySummary();
		const desiredCards: ParsedCard[] = [];

		for (const file of this.app.vault.getMarkdownFiles()) {
			summary.scannedFiles += 1;
			const parsed = await this.parseFile(file, true, options);
			if (!parsed) continue;
			summary.filesChanged += parsed.changed ? 1 : 0;
			desiredCards.push(...parsed.cards);
		}

		summary.cards = desiredCards.length;
		const client = await this.readyClient();
		await client.validateCardsCanBeAdded(desiredCards);
		await this.upsertCards(client, desiredCards, summary);

		const desiredUuids = new Set(desiredCards.map((card) => card.uuid));
		const deleteCandidates = (await client.getManagedNotes()).filter((note) => {
			const uuid = getManagedUuid(note);
			return uuid === null || !desiredUuids.has(uuid);
		});

		summary.pendingDelete = deleteCandidates.length;
		await this.deleteCandidates(client, deleteCandidates, summary, options);
		return summary;
	}

	private async parseFile(file: TFile, ensureIdentities: boolean, options?: SyncRuntimeOptions) {
		const source = await this.app.vault.read(file);
		const parsed = parseCardsDocument(source, file.path, {
			ensureIdentities,
			rootDeckName: this.settings.rootDeckName,
		});

		if (parsed.changed) {
			options?.onBeforeWrite?.(file);
			await this.app.vault.modify(file, parsed.updatedSource);
		}

		return parsed.cardsSection ? parsed : null;
	}

	private async readyClient(): Promise<AnkiConnectClient> {
		const client = new AnkiConnectClient(this.settings.ankiConnectUrl);
		await client.version();
		await client.verifyModernModels();
		return client;
	}

	private async upsertCards(client: AnkiConnectClient, cards: ParsedCard[], summary: SyncSummary): Promise<void> {
		for (const card of cards) {
			const result = await client.upsertCard(card);
			if (result.created) {
				summary.created += 1;
			} else {
				summary.updated += 1;
			}
			if (result.modelChanged) summary.modelChanged += 1;
		}
	}

	private async currentPathDeleteCandidates(client: AnkiConnectClient, path: string, desiredUuids: Set<string>): Promise<AnkiNoteInfo[]> {
		const notes = await client.getManagedNotesForPathTag(makePathTag(path));
		return notes.filter((note) => {
			const uuid = getManagedUuid(note);
			return uuid === null || !desiredUuids.has(uuid);
		});
	}

	private async deleteCandidates(client: AnkiConnectClient, candidates: AnkiNoteInfo[], summary: SyncSummary, options?: SyncRuntimeOptions): Promise<void> {
		if (candidates.length === 0) return;

		const confirmed = !this.settings.confirmBeforeDelete || await confirmDelete(this.app, candidates);

		if (!confirmed) {
			if (!options?.silent) new Notice(`Skipped deleting ${candidates.length} Anki note(s).`);
			return;
		}

		await client.deleteNotes(candidates.map((candidate) => candidate.noteId));
		summary.deleted += candidates.length;
	}
}

class DeleteConfirmationModal extends Modal {
	private resolved = false;

	constructor(
		app: App,
		private readonly candidates: AnkiNoteInfo[],
		private readonly resolve: (confirmed: boolean) => void,
	) {
		super(app);
	}

	onOpen(): void {
		const {contentEl} = this;
		const count = this.candidates.length;
		contentEl.empty();
		this.setTitle("Delete Anki notes");
		contentEl.createEl("p", {
			text: `${count} Obsidian-managed Anki note${count === 1 ? "" : "s"} no longer exist in Markdown.`,
		});

		const previewList = contentEl.createDiv({cls: "oas-delete-preview-list"});
		for (const candidate of this.candidates) {
			previewList.appendChild(renderDeletePreview(candidate));
		}

		new Setting(contentEl)
			.addButton((button) => button
				.setButtonText("Cancel")
				.onClick(() => this.finish(false)))
			.addButton((button) => button
				.setButtonText("Delete notes")
				.setWarning()
				.onClick(() => this.finish(true)));
	}

	onClose(): void {
		this.contentEl.empty();
		this.finish(false);
	}

	private finish(confirmed: boolean): void {
		if (this.resolved) return;
		this.resolved = true;
		this.resolve(confirmed);
		this.close();
	}
}

function confirmDelete(app: App, candidates: AnkiNoteInfo[]): Promise<boolean> {
	return new Promise((resolve) => {
		new DeleteConfirmationModal(app, candidates, resolve).open();
	});
}

function renderDeletePreview(note: AnkiNoteInfo): HTMLElement {
	const item = document.createElement("article");
	item.addClass("oas-delete-preview-item");

	const title = item.createDiv({cls: "oas-delete-preview-title"});
	title.createEl("span", {text: `${note.modelName} · ${note.noteId}`});

	const uuid = getManagedUuid(note);
	const path = extractPathFromTags(note.tags);
	const metadata = item.createDiv({cls: "oas-delete-preview-meta"});
	metadata.createEl("span", {text: `UUID: ${uuid ?? "missing"}`});
	metadata.createEl("span", {text: `Path: ${path ?? "missing"}`});

	const fieldPreview = item.createDiv({cls: "oas-delete-preview-fields"});
	for (const line of summarizeFields(note)) {
		fieldPreview.createDiv({text: line});
	}

	return item;
}

function summarizeFields(note: AnkiNoteInfo): string[] {
	const orderedFields = Object.entries(note.fields)
		.sort((left, right) => left[1].order - right[1].order)
		.map(([name, field]) => `${name}: ${summarizeText(field.value)}`)
		.filter((line) => line.trim().length > 0);

	return orderedFields.length > 0 ? orderedFields : ["No field preview available."];
}

function summarizeText(value: string): string {
	const normalized = decodeBasicHtml(value)
		.replace(/<[^>]*>/g, " ")
		.replace(/\s+/g, " ")
		.trim();
	return normalized.length > 180 ? `${normalized.slice(0, 180)}...` : normalized;
}

function decodeBasicHtml(value: string): string {
	return value
		.replace(/&lt;/g, "<")
		.replace(/&gt;/g, ">")
		.replace(/&amp;/g, "&")
		.replace(/&quot;/g, "\"")
		.replace(/&#039;/g, "'");
}

export function formatSummary(summary: SyncSummary): string {
	return [
		`${summary.cards} card(s)`,
		`${summary.created} created`,
		`${summary.updated} updated`,
		summary.modelChanged > 0 ? `${summary.modelChanged} model changed` : null,
		summary.deleted > 0 ? `${summary.deleted} deleted` : null,
		summary.filesChanged > 0 ? `${summary.filesChanged} file(s) updated` : null,
	].filter((part): part is string => part !== null).join(", ");
}

function emptySummary(): SyncSummary {
	return {
		scannedFiles: 0,
		cards: 0,
		created: 0,
		updated: 0,
		modelChanged: 0,
		deleted: 0,
		pendingDelete: 0,
		filesChanged: 0,
	};
}

import {MarkdownView, Notice, Platform, Plugin, TAbstractFile, TFile} from "obsidian";
import {QuickCardModal} from "./card-creator";
import {registerCardPreview} from "./preview";
import {AnkiSyncService, formatSummary} from "./sync";
import {AnkiSyncSettings, AnkiSyncSettingTab, DEFAULT_SETTINGS} from "./settings";
import {errorMessage} from "./utils";

export default class ObsidianAnkiSyncPlugin extends Plugin {
	settings: AnkiSyncSettings;
	private readonly autoSyncTimers = new Map<string, number>();
	private readonly ignoredAutoSyncPaths = new Set<string>();

	async onload(): Promise<void> {
		await this.loadSettings();

		this.addRibbonIcon("square-plus", "Create Anki card", () => {
			this.openQuickCardModal();
		});

		this.addCommand({
			id: "create-anki-card",
			name: "Create Anki card",
			checkCallback: (checking) => {
				const markdownView = this.app.workspace.getActiveViewOfType(MarkdownView);
				const file = markdownView?.file;
				if (!file || file.extension !== "md") return false;
				if (!checking) this.openQuickCardModal();
				return true;
			},
		});

		if (this.canUseAnkiConnect()) {
			this.addRibbonIcon("refresh-cw", "Sync all pages to Anki", () => {
				void this.syncAllFiles();
			});

			this.addCommand({
				id: "sync-current-page",
				name: "Sync current page to Anki",
				checkCallback: (checking) => {
					const markdownView = this.app.workspace.getActiveViewOfType(MarkdownView);
					const file = markdownView?.file;
					if (!file || file.extension !== "md") return false;
					if (!checking) void this.syncCurrentFile(file);
					return true;
				},
			});

			this.addCommand({
				id: "sync-all-pages",
				name: "Sync all pages to Anki",
				callback: () => {
					void this.syncAllFiles();
				},
			});
		}

		registerCardPreview(this, this.app, () => this.settings.rootDeckName);
		this.registerEditorMenu();
		this.registerEvent(this.app.vault.on("modify", (file) => this.handleFileModified(file)));
		this.registerEvent(this.app.vault.on("rename", (file) => this.handleFileRenamed(file)));
		this.register(() => this.clearAutoSyncTimers());
		this.addSettingTab(new AnkiSyncSettingTab(this.app, this));
	}

	onunload(): void {
		this.clearAutoSyncTimers();
	}

	async loadSettings(): Promise<void> {
		this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData() as Partial<AnkiSyncSettings>);
	}

	async saveSettings(): Promise<void> {
		await this.saveData(this.settings);
	}

	private async syncCurrentFile(file: TFile, silent = false): Promise<void> {
		if (!this.canUseAnkiConnect()) {
			if (!silent) new Notice("Anki connect sync is disabled on mobile.");
			return;
		}

		const notice = silent ? null : new Notice("Syncing current page to Anki...", 0);
		try {
			const service = this.createSyncService();
			const summary = await service.syncCurrentFile(file, {
				silent,
				onBeforeWrite: (changedFile) => this.ignoredAutoSyncPaths.add(changedFile.path),
			});

			const message = summary.cards === 0
				? "No cards found in this page."
				: `Anki sync complete: ${formatSummary(summary)}.`;
			if (notice) {
				notice.setMessage(message);
				window.setTimeout(() => notice.hide(), 3500);
			} else if (!silent) {
				new Notice(message);
			}
		} catch (error) {
			notice?.hide();
			new Notice(`Anki sync failed: ${errorMessage(error)}`, 8000);
			console.error(error);
		}
	}

	private async syncAllFiles(): Promise<void> {
		if (!this.canUseAnkiConnect()) {
			new Notice("Anki connect sync is disabled on mobile.");
			return;
		}

		const notice = new Notice("Syncing all pages to Anki...", 0);
		try {
			const service = this.createSyncService();
			const summary = await service.syncAllFiles({
				onBeforeWrite: (changedFile) => this.ignoredAutoSyncPaths.add(changedFile.path),
			});
			notice.setMessage(`Anki sync complete: ${formatSummary(summary)} across ${summary.scannedFiles} file(s).`);
			window.setTimeout(() => notice.hide(), 5000);
		} catch (error) {
			notice.hide();
			new Notice(`Anki sync failed: ${errorMessage(error)}`, 8000);
			console.error(error);
		}
	}

	private handleFileModified(file: TAbstractFile): void {
		if (!(file instanceof TFile) || file.extension !== "md") return;
		if (this.ignoredAutoSyncPaths.delete(file.path)) return;
		if (!this.canUseAnkiConnect()) return;
		if (!this.settings.autoSyncOnSave) return;

		this.queueAutoSync(file);
	}

	private handleFileRenamed(file: TAbstractFile): void {
		if (!(file instanceof TFile) || file.extension !== "md") return;
		if (!this.canUseAnkiConnect()) return;
		if (!this.settings.autoSyncOnSave) return;
		this.queueAutoSync(file);
	}

	private queueAutoSync(file: TFile): void {
		const existingTimer = this.autoSyncTimers.get(file.path);
		if (existingTimer !== undefined) {
			window.clearTimeout(existingTimer);
		}

		const timer = window.setTimeout(() => {
			this.autoSyncTimers.delete(file.path);
			void this.syncCurrentFile(file, true);
		}, 1200);

		this.autoSyncTimers.set(file.path, timer);
	}

	private createSyncService(): AnkiSyncService {
		return new AnkiSyncService(this.app, this.settings);
	}

	private openQuickCardModal(): void {
		const markdownView = this.app.workspace.getActiveViewOfType(MarkdownView);
		const selectedText = markdownView?.editor.getSelection();
		const initialText = selectedText?.trim() ? selectedText : undefined;

		new QuickCardModal(this.app, ({file, shouldSync}) => {
			new Notice("Anki card inserted.");
			if (shouldSync) {
				void this.syncCurrentFile(file);
			}
		}, (file) => this.ignoredAutoSyncPaths.add(file.path), {
			allowSync: this.canUseAnkiConnect(),
			file: markdownView?.file ?? null,
			editor: markdownView?.editor,
			initialText,
		}).open();
	}

	private registerEditorMenu(): void {
		this.registerEvent(this.app.workspace.on("editor-menu", (menu, editor, view) => {
			if (!(view instanceof MarkdownView)) return;
			if (!editor.getSelection().trim()) return;

			menu.addItem((item) => item
				.setTitle("Create Anki card")
				.setIcon("square-plus")
				.onClick(() => {
					this.openQuickCardModal();
				}));
		}));
	}

	private clearAutoSyncTimers(): void {
		for (const timer of this.autoSyncTimers.values()) {
			window.clearTimeout(timer);
		}
		this.autoSyncTimers.clear();
	}

	private canUseAnkiConnect(): boolean {
		return !Platform.isMobileApp;
	}
}

import {requestUrl} from "obsidian";
import {MANAGED_TAG, SUPPORTED_MODELS, TEMPLATE_SETUP_HINT} from "./constants";
import {prepareFieldsForAnki} from "./field-encoding";
import {AnkiFields, ParsedCard} from "./parser";
import {extractUuidFromTags, makeUuidTag} from "./tags";
import {errorMessage} from "./utils";

export interface AnkiNoteInfo {
	noteId: number;
	modelName: string;
	tags: string[];
	fields: Record<string, {value: string; order: number}>;
	cards: number[];
}

export interface AnkiUpsertResult {
	noteId: number;
	created: boolean;
	modelChanged: boolean;
}

interface AddNotePayload {
	deckName: string;
	modelName: string;
	fields: AnkiFields;
	tags: string[];
	options: {
		allowDuplicate: boolean;
	};
}

interface CanAddNoteResult {
	canAdd: boolean;
	error?: string;
}

export class AnkiConnectClient {
	constructor(private readonly url: string) {}

	async version(): Promise<number> {
		return this.invoke<number>("version");
	}

	async modelNames(): Promise<string[]> {
		return this.invoke<string[]>("modelNames");
	}

	async verifyModernModels(): Promise<void> {
		const modelNames = await this.modelNames();
		const missing = SUPPORTED_MODELS.filter((modelName) => !modelNames.includes(modelName));
		if (missing.length > 0) {
			throw new Error(`${TEMPLATE_SETUP_HINT}\nMissing: ${missing.join(", ")}`);
		}
	}

	async createDeck(deck: string): Promise<void> {
		await this.invoke("createDeck", {deck});
	}

	async findNotes(query: string): Promise<number[]> {
		return this.invoke<number[]>("findNotes", {query});
	}

	async notesInfo(notes: number[]): Promise<AnkiNoteInfo[]> {
		if (notes.length === 0) return [];
		return this.invoke<AnkiNoteInfo[]>("notesInfo", {notes});
	}

	async addNote(card: ParsedCard): Promise<number> {
		return this.invoke<number>("addNote", {
			note: this.toAddNotePayload(card),
		});
	}

	async updateNote(noteId: number, fields: AnkiFields, tags: string[]): Promise<void> {
		const escapedFields = prepareFieldsForAnki(fields);
		try {
			await this.invoke("updateNoteFields", {
				note: {
					id: noteId,
					fields: escapedFields,
				},
			});
			await this.invoke("updateNoteTags", {
				note: noteId,
				tags,
			});
		} catch (error) {
			if (!isUnsupportedAction(error)) throw error;
			await this.invoke("updateNote", {
				note: {
					id: noteId,
					fields: escapedFields,
					tags,
				},
			});
		}
	}

	async updateNoteModel(noteId: number, modelName: string, fields: AnkiFields, tags: string[]): Promise<void> {
		const escapedFields = prepareFieldsForAnki(fields);
		try {
			await this.invoke("updateNoteModel", {
				note: {
					id: noteId,
					modelName,
					fields: escapedFields,
					tags,
				},
			});
		} catch (error) {
			if (!isUnsupportedAction(error)) throw error;
			throw new Error(`Anki note ${noteId} uses a different model. Delete it manually or update AnkiConnect to use updateNoteModel.`);
		}
	}

	async validateCardsCanBeAdded(cards: ParsedCard[]): Promise<void> {
		if (cards.length === 0) return;
		const localFailures = cards.filter((card) => !card.modelName.startsWith("Cloze-Modern") && fieldsContainClozeSyntax(card.fields));
		if (localFailures.length > 0) {
			const details = localFailures.map((card) => {
				return `#${card.ordinal + 1} ${card.modelName}: Basic note types cannot contain Anki cloze syntax like {{c1::...}} (${previewField(card.fields)})`;
			});
			throw new Error(`Anki rejected ${localFailures.length} card(s). Nothing was synced.\n${details.join("\n")}`);
		}

		for (const deckName of new Set(cards.map((card) => card.deckName))) {
			await this.createDeck(deckName);
		}

		const notes = cards.map((card) => this.toAddNotePayload(card));
		let results: CanAddNoteResult[];
		try {
			results = await this.invoke<CanAddNoteResult[]>("canAddNotesWithErrorDetail", {notes});
		} catch (error) {
			if (!isUnsupportedAction(error)) throw error;
			const fallback = await this.invoke<boolean[]>("canAddNotes", {notes});
			results = fallback.map((canAdd) => ({canAdd, error: canAdd ? undefined : "cannot create note for unknown reason"}));
		}

		const failures = results
			.map((result, index) => ({result, card: cards[index]}))
			.filter((item): item is {result: CanAddNoteResult; card: ParsedCard} => item.card !== undefined && !item.result.canAdd);

		if (failures.length === 0) return;

		const details = failures.map(({result, card}) => {
			return `#${card.ordinal + 1} ${card.modelName}: ${result.error ?? "cannot create note"} (${previewField(card.fields)})`;
		});
		throw new Error(`Anki rejected ${failures.length} card(s). Nothing was synced.\n${details.join("\n")}`);
	}

	async changeDeck(cards: number[], deck: string): Promise<void> {
		if (cards.length === 0) return;
		await this.createDeck(deck);
		await this.invoke("changeDeck", {cards, deck});
	}

	async deleteNotes(notes: number[]): Promise<void> {
		if (notes.length === 0) return;
		await this.invoke("deleteNotes", {notes});
	}

	async upsertCard(card: ParsedCard): Promise<AnkiUpsertResult> {
		await this.createDeck(card.deckName);

		const noteIds = await this.findNotes(`tag:${MANAGED_TAG} tag:${makeUuidTag(card.uuid)}`);
		if (noteIds.length === 0) {
			const noteId = await this.addNote(card);
			return {noteId, created: true, modelChanged: false};
		}

		const noteId = noteIds[0];
		if (noteId === undefined) {
			const createdNoteId = await this.addNote(card);
			return {noteId: createdNoteId, created: true, modelChanged: false};
		}

		const [existing] = await this.notesInfo([noteId]);
		if (!existing) {
			const createdNoteId = await this.addNote(card);
			return {noteId: createdNoteId, created: true, modelChanged: false};
		}

		const modelChanged = existing.modelName !== card.modelName;
		if (modelChanged) {
			await this.updateNoteModel(noteId, card.modelName, card.fields, card.ankiTags);
		} else {
			await this.updateNote(noteId, card.fields, card.ankiTags);
		}

		const [updatedInfo] = await this.notesInfo([noteId]);
		await this.changeDeck(updatedInfo?.cards ?? existing.cards, card.deckName);
		return {noteId, created: false, modelChanged};
	}

	async getManagedNotes(): Promise<AnkiNoteInfo[]> {
		return this.notesInfo(await this.findNotes(`tag:${MANAGED_TAG}`));
	}

	async getManagedNotesForPathTag(pathTag: string): Promise<AnkiNoteInfo[]> {
		return this.notesInfo(await this.findNotes(`tag:${MANAGED_TAG} tag:${pathTag}`));
	}

	private toAddNotePayload(card: ParsedCard): AddNotePayload {
		return {
			deckName: card.deckName,
			modelName: card.modelName,
			fields: prepareFieldsForAnki(card.fields),
			tags: card.ankiTags,
			options: {
				allowDuplicate: true,
			},
		};
	}

	private async invoke<T = null>(action: string, params?: Record<string, unknown>): Promise<T> {
		let response;
		try {
			response = await requestUrl({
				url: this.url,
				method: "POST",
				contentType: "application/json",
				throw: false,
				body: JSON.stringify({
					action,
					version: 6,
					params: params ?? {},
				}),
			});
		} catch (error) {
			throw new Error(`Cannot connect to AnkiConnect at ${this.url}. Make sure Anki is running and AnkiConnect is installed. ${errorMessage(error)}`);
		}

		if (response.status >= 400) {
			throw new Error(`AnkiConnect ${action} failed with HTTP ${response.status}.`);
		}

		const payload = response.json as {result: T; error: string | null} | null;
		if (!payload || typeof payload !== "object") {
			throw new Error(`AnkiConnect ${action} returned an unexpected response. Is AnkiConnect up to date?`);
		}
		if (payload.error) {
			throw new Error(payload.error);
		}

		return payload.result;
	}
}

export function getManagedUuid(note: AnkiNoteInfo): string | null {
	return extractUuidFromTags(note.tags);
}

function isUnsupportedAction(error: unknown): boolean {
	const message = errorMessage(error).toLowerCase();
	return message.includes("unsupported action") || message.includes("unknown action");
}

function previewField(fields: AnkiFields): string {
	const value = "Text" in fields ? fields.Text : fields.Front;
	return value.replace(/\s+/g, " ").slice(0, 80);
}

function fieldsContainClozeSyntax(fields: AnkiFields): boolean {
	const values = "Text" in fields ? [fields.Text, fields.Extra] : [fields.Front, fields.Back];
	return values.some((value) => /\{\{c\d+::/i.test(value));
}

import {App, Platform, Plugin, PluginSettingTab, Setting} from "obsidian";
import {DEFAULT_ANKI_CONNECT_URL, DEFAULT_ROOT_DECK} from "./constants";

export interface AnkiSyncSettings {
	ankiConnectUrl: string;
	rootDeckName: string;
	autoSyncOnSave: boolean;
	confirmBeforeDelete: boolean;
}

export const DEFAULT_SETTINGS: AnkiSyncSettings = {
	ankiConnectUrl: DEFAULT_ANKI_CONNECT_URL,
	rootDeckName: DEFAULT_ROOT_DECK,
	autoSyncOnSave: false,
	confirmBeforeDelete: true,
};

export interface SettingsHost {
	settings: AnkiSyncSettings;
	saveSettings(): Promise<void>;
}

export class AnkiSyncSettingTab extends PluginSettingTab {
	constructor(
		app: App,
		private readonly plugin: Plugin & SettingsHost,
	) {
		super(app, plugin);
	}

	display(): void {
		const {containerEl} = this;
		containerEl.empty();
		const canUseAnkiConnect = !Platform.isMobileApp;

		new Setting(containerEl)
			.setName("Connection")
			.setHeading();

		if (!canUseAnkiConnect) {
			new Setting(containerEl)
				.setName("Mobile mode")
				.setDesc("Card preview and card creation are available. Anki connect sync is disabled on mobile.");
		}

		new Setting(containerEl)
			.setName("Anki connect endpoint")
			.setDesc("Local Anki connect endpoint.")
			.addText((text) => {
				text
					.setPlaceholder(DEFAULT_ANKI_CONNECT_URL)
					.setValue(this.plugin.settings.ankiConnectUrl)
					.setDisabled(!canUseAnkiConnect)
					.onChange(async (value) => {
						this.plugin.settings.ankiConnectUrl = value.trim() || DEFAULT_ANKI_CONNECT_URL;
						await this.plugin.saveSettings();
					});
			});

		new Setting(containerEl)
			.setName("Root deck")
			.setDesc("Cards sync into this Anki deck, with the Obsidian path mirrored below it.")
			.addText((text) => {
				text
					.setPlaceholder(DEFAULT_ROOT_DECK)
					.setValue(this.plugin.settings.rootDeckName)
					.setDisabled(!canUseAnkiConnect)
					.onChange(async (value) => {
						this.plugin.settings.rootDeckName = value.trim() || DEFAULT_ROOT_DECK;
						await this.plugin.saveSettings();
					});
			});

		new Setting(containerEl)
			.setName("Sync on save")
			.setDesc("Automatically sync Markdown files that contain a cards section after they are saved.")
			.addToggle((toggle) => {
				toggle
					.setValue(this.plugin.settings.autoSyncOnSave)
					.setDisabled(!canUseAnkiConnect)
					.onChange(async (value) => {
						this.plugin.settings.autoSyncOnSave = value;
						await this.plugin.saveSettings();
					});
			});

		new Setting(containerEl)
			.setName("Confirm before deleting")
			.setDesc("Ask before deleting Obsidian-managed notes that no longer exist in Markdown.")
			.addToggle((toggle) => {
				toggle
					.setValue(this.plugin.settings.confirmBeforeDelete)
					.setDisabled(!canUseAnkiConnect)
					.onChange(async (value) => {
						this.plugin.settings.confirmBeforeDelete = value;
						await this.plugin.saveSettings();
					});
			});
	}
}

import {DEFAULT_ROOT_DECK, MANAGED_TAG, MODEL_ALIASES, SupportedModelName, SUPPORTED_MODELS} from "./constants";
import {deckNameForPath, makePathTag, makeUuidTag, sanitizeUserTag, uniqueTags} from "./tags";
import {trimOuterBlankLines} from "./utils";

export interface ParsedCardsDocument {
	cards: ParsedCard[];
	cardsSection: CardsSection | null;
	source: string;
	updatedSource: string;
	changed: boolean;
	pageTags: string[];
}

export interface CardsSection {
	headingLine: number;
	startOffset: number;
	contentStartOffset: number;
	endOffset: number;
	headingText: string;
}

export interface ParsedCard {
	uuid: string;
	path: string;
	ordinal: number;
	modelName: SupportedModelName;
	fields: AnkiFields;
	userTags: string[];
	ankiTags: string[];
	deckName: string;
	block: string;
	updatedBlock: string;
}

export type AnkiFields =
	| {Text: string; Extra: string}
	| {Front: string; Back: string};

interface ParseOptions {
	ensureIdentities: boolean;
	rootDeckName: string;
	path: string;
	usedUuids?: Set<string>;
}

interface BlockMeta {
	type: string | null;
	uuid: string | null;
	path: string | null;
	tags: string[];
}

const CARDS_HEADING = /^(#{1,6})\s+Cards\s*$/i;
const HEADING_LINE = /^(#{1,6})\s/;
const BLOCK_SEPARATOR = /^\s*---\s*$/;
const META_LINE = /^\s*(type|tag|tags|uuid|path)\s*:\s*(.*?)\s*$/i;
const FENCE_LINE = /^\s*(```|~~~)/;
const CLOZE_PATTERN = /\{\{c\d+::[\s\S]*?\}\}/i;
const FRONT_MARKER = /^\s*Front\s*$/i;
const BACK_MARKER = /^\s*Back\s*$/i;

export function parseCardsDocument(source: string, path: string, options?: Partial<ParseOptions>): ParsedCardsDocument {
	const rootDeckName = options?.rootDeckName ?? DEFAULT_ROOT_DECK;
	const ensureIdentities = options?.ensureIdentities ?? false;
	const pageTags = extractPageTags(source);
	const cardsSection = findCardsSection(source);

	if (!cardsSection) {
		return {
			cards: [],
			cardsSection: null,
			source,
			updatedSource: source,
			changed: false,
			pageTags,
		};
	}

	const sectionContent = source.slice(cardsSection.contentStartOffset, cardsSection.endOffset);
	const blocks = splitCardBlocks(sectionContent);
	const cards: ParsedCard[] = [];
	const usedUuids = new Set<string>();
	let changed = false;
	let rebuiltSection = "";

	for (let index = 0; index < blocks.length; index += 1) {
		const split = blocks[index];
		if (!split) continue;

		if (!hasCardContent(split.block)) {
			rebuiltSection += split.block + split.separator;
			continue;
		}

		const parsed = parseCardBlock(split.block, {
			ensureIdentities,
			rootDeckName,
			path,
			usedUuids,
		}, pageTags, cards.length);

		cards.push(parsed.card);
		rebuiltSection += parsed.card.updatedBlock + split.separator;
		changed = changed || parsed.changed;
	}

	const updatedSource = changed
		? source.slice(0, cardsSection.contentStartOffset) + rebuiltSection + source.slice(cardsSection.endOffset)
		: source;

	return {
		cards,
		cardsSection,
		source,
		updatedSource,
		changed,
		pageTags,
	};
}

export function findCardsSection(source: string): CardsSection | null {
	const lines = source.split(/\n/);
	let offset = 0;
	let inFence = false;

	for (let lineNumber = 0; lineNumber < lines.length; lineNumber += 1) {
		const rawLine = lines[lineNumber] ?? "";
		const line = rawLine.replace(/\r$/, "");
		const lineStart = offset;
		offset += rawLine.length + 1;

		if (FENCE_LINE.test(line)) {
			inFence = !inFence;
			continue;
		}
		if (inFence) continue;

		const headingMatch = line.match(CARDS_HEADING);
		if (!headingMatch) continue;

		const headingLevel = headingMatch[1]?.length ?? 1;
		const lineEnd = lineStart + rawLine.length;
		const contentStartOffset = lineEnd + (lineEnd < source.length && source[lineEnd] === "\n" ? 1 : 0);
		return {
			headingLine: lineNumber,
			startOffset: lineStart,
			contentStartOffset,
			endOffset: findSectionEndOffset(source, lines, lineNumber + 1, headingLevel, offset),
			headingText: line.trim(),
		};
	}

	return null;
}

function findSectionEndOffset(source: string, lines: string[], fromLine: number, headingLevel: number, fromOffset: number): number {
	let offset = fromOffset;
	let inFence = false;

	for (let lineNumber = fromLine; lineNumber < lines.length; lineNumber += 1) {
		const rawLine = lines[lineNumber] ?? "";
		const line = rawLine.replace(/\r$/, "");

		if (FENCE_LINE.test(line)) {
			inFence = !inFence;
		} else if (!inFence) {
			const headingMatch = line.match(HEADING_LINE);
			const level = headingMatch?.[1]?.length;
			if (level !== undefined && level <= headingLevel) {
				return offset;
			}
		}

		offset += rawLine.length + 1;
	}

	return source.length;
}

export function extractPageTags(source: string): string[] {
	const tags = new Set<string>();

	for (const tag of extractFrontmatterTags(source)) {
		tags.add(tag);
	}

	const inlineTagPattern = /(^|[\s([>])#([\p{L}\p{N}_/-]+(?:\/[\p{L}\p{N}_/-]+)*)/gu;
	let match: RegExpExecArray | null;
	while ((match = inlineTagPattern.exec(stripFrontmatter(source))) !== null) {
		const value = match[2];
		if (value) tags.add(value);
	}

	return uniqueTags(Array.from(tags).map((tag) => sanitizeUserTag(tag)).filter((tag): tag is string => tag !== null));
}

export function normalizeModelName(value: string | null): SupportedModelName | null {
	if (!value) return null;
	const trimmed = value.trim();
	const direct = SUPPORTED_MODELS.find((modelName) => modelName.toLowerCase() === trimmed.toLowerCase());
	if (direct) return direct;
	return MODEL_ALIASES[trimmed.toLowerCase()] ?? null;
}

function parseCardBlock(block: string, options: ParseOptions, pageTags: string[], ordinal: number): {card: ParsedCard; changed: boolean} {
	const meta = extractBlockMeta(block);
	let uuid = normalizeUuid(meta.uuid) ?? createUuid();
	if (options.usedUuids?.has(uuid)) {
		uuid = createUuid();
	}
	options.usedUuids?.add(uuid);
	const modelName = chooseModelName(block, meta.type);
	const fields = parseFields(block, modelName);
	const mergedUserTags = uniqueTags([...pageTags, ...meta.tags].map((tag) => sanitizeUserTag(tag)).filter((tag): tag is string => tag !== null));
	const ankiTags = uniqueTags([
		MANAGED_TAG,
		makeUuidTag(uuid),
		makePathTag(options.path),
		...mergedUserTags,
	]);
	const updatedBlock = options.ensureIdentities ? ensureIdentityLines(block, uuid, options.path) : block;
	const deckName = deckNameForPath(options.rootDeckName, options.path);

	return {
		card: {
			uuid,
			path: options.path,
			ordinal,
			modelName,
			fields,
			userTags: mergedUserTags,
			ankiTags,
			deckName,
			block,
			updatedBlock,
		},
		changed: options.ensureIdentities && updatedBlock !== block,
	};
}

function chooseModelName(block: string, explicitType: string | null): SupportedModelName {
	const explicit = normalizeModelName(explicitType);
	if (explicit) return explicit;
	if (CLOZE_PATTERN.test(block)) return "Cloze-Modern";
	return "Basic-Modern";
}

function parseFields(block: string, modelName: SupportedModelName): AnkiFields {
	const contentLines = contentLinesOf(block);

	if (modelName.startsWith("Cloze-Modern")) {
		const extraIndex = contentLines.findIndex((line) => /^\s*Extra\s*$/i.test(line));
		if (extraIndex >= 0) {
			return {
				Text: trimOuterBlankLines(contentLines.slice(0, extraIndex).join("\n")),
				Extra: trimOuterBlankLines(contentLines.slice(extraIndex + 1).join("\n")),
			};
		}
		return {
			Text: trimOuterBlankLines(contentLines.join("\n")),
			Extra: "",
		};
	}

	const frontIndex = contentLines.findIndex((line) => FRONT_MARKER.test(line));
	const backIndex = contentLines.findIndex((line) => BACK_MARKER.test(line));

	if (frontIndex >= 0 && backIndex > frontIndex) {
		return {
			Front: trimOuterBlankLines(contentLines.slice(frontIndex + 1, backIndex).join("\n")),
			Back: trimOuterBlankLines(contentLines.slice(backIndex + 1).join("\n")),
		};
	}

	return {
		Front: trimOuterBlankLines(contentLines.join("\n")),
		Back: "",
	};
}

function extractBlockMeta(block: string): BlockMeta {
	const meta: BlockMeta = {
		type: null,
		uuid: null,
		path: null,
		tags: [],
	};

	let inFence = false;
	for (const line of block.split(/\n/)) {
		if (FENCE_LINE.test(line.replace(/\r$/, ""))) {
			inFence = !inFence;
			continue;
		}
		if (inFence) continue;

		const match = line.match(META_LINE);
		if (!match) continue;

		const key = match[1]?.toLowerCase();
		const value = match[2]?.trim() ?? "";
		if (key === "type") meta.type = value;
		if (key === "uuid") meta.uuid = value;
		if (key === "path") meta.path = value;
		if (key === "tag" || key === "tags") meta.tags.push(...splitTags(value));
	}

	return meta;
}

function ensureIdentityLines(block: string, uuid: string, path: string): string {
	const newline = block.endsWith("\n") ? "\n" : "";
	const lines: string[] = [];
	let inFence = false;

	for (const line of block.replace(/\n$/, "").split(/\n/)) {
		if (FENCE_LINE.test(line.replace(/\r$/, ""))) {
			inFence = !inFence;
			lines.push(line);
			continue;
		}

		if (!inFence) {
			const match = line.match(META_LINE);
			if (match) {
				const key = match[1]?.toLowerCase();
				if (key === "uuid" || key === "path") continue;
			}
		}

		lines.push(line);
	}

	while (lines.length > 0 && (lines[lines.length - 1] ?? "").trim() === "") {
		lines.pop();
	}

	lines.push(`uuid: ${uuid}`, `path: ${path}`);
	return lines.join("\n") + newline;
}

function splitCardBlocks(sectionContent: string): Array<{block: string; separator: string}> {
	const lines = sectionContent.split(/(\n)/);
	const blocks: Array<{block: string; separator: string}> = [];
	let current = "";
	let inFence = false;

	for (let index = 0; index < lines.length; index += 2) {
		const line = lines[index] ?? "";
		const newline = lines[index + 1] ?? "";

		if (FENCE_LINE.test(line.replace(/\r$/, ""))) {
			inFence = !inFence;
		} else if (!inFence && BLOCK_SEPARATOR.test(line)) {
			blocks.push({block: current, separator: line + newline});
			current = "";
			continue;
		}

		current += line + newline;
	}

	if (current.length > 0) {
		blocks.push({block: current, separator: ""});
	}

	return blocks;
}

function hasCardContent(block: string): boolean {
	return contentLinesOf(block).some((line) => line.trim() !== "");
}

function contentLinesOf(block: string): string[] {
	const lines: string[] = [];
	let inFence = false;

	for (const line of block.split(/\n/)) {
		if (FENCE_LINE.test(line.replace(/\r$/, ""))) {
			inFence = !inFence;
			lines.push(line);
			continue;
		}
		if (!inFence && isMetadataLine(line)) continue;
		lines.push(line);
	}

	return lines;
}

function isMetadataLine(line: string): boolean {
	return META_LINE.test(line);
}

function splitTags(value: string): string[] {
	if (!value.trim()) return [];
	const bracketList = value.match(/^\[(.*)\]$/);
	const normalized = bracketList ? bracketList[1] ?? "" : value;
	return normalized
		.split(/[,\s]+/)
		.map((tag) => tag.trim().replace(/^["']|["']$/g, ""))
		.filter((tag) => tag.length > 0);
}

function extractFrontmatterTags(source: string): string[] {
	if (!source.startsWith("---")) return [];
	const end = source.indexOf("\n---", 3);
	if (end < 0) return [];
	const frontmatter = source.slice(3, end).split(/\n/);
	const tags: string[] = [];

	for (let index = 0; index < frontmatter.length; index += 1) {
		const line = frontmatter[index] ?? "";
		const inline = line.match(/^\s*tags\s*:\s*(.*?)\s*$/i);
		if (!inline) continue;

		const value = inline[1] ?? "";
		if (value.trim().startsWith("[")) {
			tags.push(...splitTags(value));
			continue;
		}

		if (value.trim().length > 0) {
			tags.push(...splitTags(value));
			continue;
		}

		for (let listIndex = index + 1; listIndex < frontmatter.length; listIndex += 1) {
			const listLine = frontmatter[listIndex] ?? "";
			const listItem = listLine.match(/^\s*-\s*(.*?)\s*$/);
			if (!listItem) break;
			tags.push(listItem[1] ?? "");
		}
	}

	return tags;
}

function stripFrontmatter(source: string): string {
	if (!source.startsWith("---")) return source;
	const end = source.indexOf("\n---", 3);
	return end >= 0 ? source.slice(end + 4) : source;
}

function createUuid(): string {
	if (typeof globalThis.crypto?.randomUUID === "function") {
		return globalThis.crypto.randomUUID();
	}

	return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (char) => {
		const random = Math.floor(Math.random() * 16);
		const value = char === "x" ? random : (random & 0x3) | 0x8;
		return value.toString(16);
	});
}

function normalizeUuid(value: string | null): string | null {
	if (!value) return null;
	const normalized = value.trim().toLowerCase();
	if (normalized.length === 0) return null;
	if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(normalized)) {
		return null;
	}
	return normalized;
}

import {findCardsSection} from "./parser";
import {trimOuterBlankLines} from "./utils";

export type QuickCardKind =
	| "cloze"
	| "cloze-typing"
	| "basic"
	| "basic-reversed"
	| "basic-typing";

export interface QuickCardDraft {
	kind: QuickCardKind;
	front: string;
	back: string;
	tags: string;
	syncAfterInsert: boolean;
}

export interface ClozeWrapResult {
	value: string;
	selectionStart: number;
	selectionEnd: number;
}

export function buildCardBlock(draft: QuickCardDraft): string {
	const lines: string[] = [];
	const typeLine = typeLineForKind(draft.kind);
	if (typeLine) lines.push(typeLine);

	if (draft.kind.startsWith("basic")) {
		lines.push("Front", draft.front.trim(), "Back", draft.back.trim());
	} else {
		lines.push(draft.front.trim());
		if (draft.back.trim().length > 0) {
			lines.push("Extra", draft.back.trim());
		}
	}

	if (draft.tags.trim().length > 0) {
		lines.push(`tags: ${draft.tags.trim()}`);
	}

	lines.push("uuid:", "path:");
	return trimOuterBlankLines(lines.join("\n")) + "\n";
}

export interface CardsInsertion {
	offset: number;
	text: string;
}

export function buildCardsInsertion(source: string, block: string): CardsInsertion {
	const section = findCardsSection(source);
	if (!section) {
		const prefix = source.trim().length === 0 ? "" : ensureTrailingBlankLines(source, 2);
		return {
			offset: source.length,
			text: `${prefix}# Cards\n${block}---\n`,
		};
	}

	const sectionContent = source.slice(section.contentStartOffset, section.endOffset);
	const leadingNewline = section.endOffset > 0 && source[section.endOffset - 1] !== "\n" ? "\n" : "";
	const separator = sectionContent.trim().length > 0 && !endsWithSeparator(sectionContent) ? "---\n" : "";

	return {
		offset: section.endOffset,
		text: `${leadingNewline}${separator}${block}---\n`,
	};
}

function endsWithSeparator(source: string): boolean {
	const lines = source.trimEnd().split("\n");
	return (lines[lines.length - 1] ?? "").trim() === "---";
}

function ensureTrailingBlankLines(source: string, count: number): string {
	const existing = source.match(/\n*$/)?.[0].length ?? 0;
	return "\n".repeat(Math.max(0, count - existing));
}

export function wrapNextCloze(value: string, selectionStart: number, selectionEnd: number): ClozeWrapResult {
	const start = clamp(selectionStart, 0, value.length);
	const end = clamp(selectionEnd, start, value.length);
	const clozeNumber = nextClozeNumber(value);
	const opener = `{{c${clozeNumber}::`;
	const selectedText = value.slice(start, end) || "answer";
	const wrapped = `${opener}${selectedText}}}`;
	const nextValue = value.slice(0, start) + wrapped + value.slice(end);
	const nextSelectionStart = start + opener.length;
	const nextSelectionEnd = nextSelectionStart + selectedText.length;

	return {
		value: nextValue,
		selectionStart: nextSelectionStart,
		selectionEnd: nextSelectionEnd,
	};
}

function typeLineForKind(kind: QuickCardKind): string | null {
	if (kind === "cloze-typing") return "type: Cloze-Modern-Typing";
	if (kind === "basic-reversed") return "type: Basic-Modern-Reversed";
	if (kind === "basic-typing") return "type: Basic-Modern-Typing";
	return null;
}

function nextClozeNumber(value: string): number {
	const pattern = /\{\{c(\d+)::/g;
	let next = 1;
	let match: RegExpExecArray | null;

	while ((match = pattern.exec(value)) !== null) {
		const number = Number(match[1]);
		if (Number.isFinite(number)) next = Math.max(next, number + 1);
	}

	return next;
}

function clamp(value: number, min: number, max: number): number {
	return Math.min(Math.max(value, min), max);
}
